//! Live wrapper/occupancy ownership. Artwork and path allocation remain with
//! their existing owners; MAP attribute bytes retain their original high bit.
use super::{self as native,Error,Occupant,WrapperActor,Terrain,Handshake};
use crate::{Game,original_combat,original_collision::Contact,original_path_contact::game::Boundary};
fn boundary(e:Error)->Boundary{match e{Error::MissingMaskByte(a)=>Boundary::MissingCollisionMask(a),Error::MissingTerrain(c)=>Boundary::MissingTerrain(c)}}
fn point(u:&crate::Unit)->[i16;2]{[if u.native_transport.as_ref().is_some_and(|a|a.phase==crate::original_transport::Phase::Inside){10000}else{(u.x/2.).floor()as i16},(u.y/2.).floor()as i16]}
struct TerrainEnv<'a>(&'a mut Game);
impl Terrain for TerrainEnv<'_>{fn read(&mut self,c:i16)->Result<u8,Error>{self.0.dynamic_collision_terrain(c)}fn write(&mut self,c:i16,value:u8)->Result<(),Error>{
 if !(0..16384).contains(&i32::from(c)){return Err(Error::MissingTerrain(c));}let n=c as usize;let(x,y)=(n&127,n>>7);let mut written=false;
 if x<self.0.map.width&&y<self.0.map.height{if let Some(old)=self.0.map.terrain_codes.get_mut(y*self.0.map.width+x){*old=value;written=true;}}
 if let Some(old)=self.0.map.native_terrain_plane.get_mut(n){*old=value;written=true;}if written{Ok(())}else{Err(Error::MissingTerrain(c))}
}}
impl Game{
 fn dynamic_collision_terrain(&self,c:i16)->Result<u8,Error>{if !(0..16384).contains(&i32::from(c)){return Err(Error::MissingTerrain(c));}let n=c as usize;let(x,y)=(n&127,n>>7);if x<self.map.width&&y<self.map.height{self.map.terrain_codes.get(y*self.map.width+x).copied()}else{self.map.native_terrain_plane.get(n).copied()}.ok_or(Error::MissingTerrain(c))}
 pub(crate) fn initialize_native_terrain_tag(&mut self,index:usize)->Result<(),Boundary>{let u=self.units.get(index).ok_or(Boundary::MissingActor)?;if u.native_slot.is_none(){return Ok(());}let code=self.dynamic_collision_terrain(u.native_cell10 as i16).map_err(boundary)?;let tag=native::initial_terrain_tag(&self.native_collision_masks,u.native_footprint18,code).map_err(boundary)?;self.units[index].native_terrain_tag63=tag;Ok(())}
 pub(crate) fn native_collision_mask_value(&self,token:u32,code:u8)->Result<u8,Boundary>{self.native_collision_masks.value(token,code).map_err(boundary)}
 ///Returns corrected UNIT position in Contact.position and unchanged native
 ///global proposed position in Contact.attempted. The caller commits them at
 ///its original leaf/518e0 boundaries; they must not be swapped or collapsed.
 pub(crate) fn native_wrapped_collision(&mut self,index:usize,attempted:[i16;2])->Result<(bool,Contact),Boundary>{
  let u=self.units.get(index).ok_or(Boundary::MissingActor)?;let vehicle=u.native_class7c==1;let own=u.native_slot.and_then(|slot|self.native_group_rosters.members[slot].as_ref()).map(|m|usize::from(m.group));let group=own.and_then(|g|self.native_group_rosters.pool.get(g));let command=group.map_or(0,|g|g.roster[58]as i8);let goal=group.map(|g|[g.word(44),g.word(46)]);
  if vehicle&&matches!(original_combat::facing(u.angle),0|1|7)&&group.is_none(){return Err(Boundary::MissingGroup(own.unwrap_or(255)as i16));}
  let mut actor=WrapperActor{position:point(u),permission:u.native_permission1c,footprint:u.native_footprint18,terrain_tag:u.native_terrain_tag63,heading:original_combat::facing(u.angle),pausebc:u.native_contact_pausebc,counter67:u.native_counter67};
  let mut masks=std::mem::take(&mut self.native_collision_masks);let result=native::wrapped(&mut actor,&mut masks,attempted,vehicle,command,||goal.is_some_and(|p|self.native_world_buildings().is_some_and(|bs|crate::original_world_contact::first_building(&bs,p,false,false).is_some_and(|(slot,_)|bs[slot].kind==0))),|cell|self.dynamic_collision_terrain(cell));self.native_collision_masks=masks;
  let u=&mut self.units[index];u.native_permission1c=actor.permission;u.native_contact_pausebc=actor.pausebc;u.native_counter67=actor.counter67;result.map_err(boundary)
 }
 fn occupancy_unit_index(&self,slot:usize)->Result<usize,Boundary>{self.units.iter().rposition(|u|u.native_slot==Some(slot)).or_else(||self.native_cached_unit_id(slot).and_then(|id|self.units.iter().position(|u|u.id==id))).ok_or(Boundary::MissingUnit(slot))}
 fn occupancy_actor(&self,index:usize)->Result<Occupant,Boundary>{let u=self.units.get(index).ok_or(Boundary::MissingActor)?;let slot=u.native_slot.ok_or(Boundary::MissingActor)?;let m=self.native_group_rosters.members[slot].as_ref().ok_or(Boundary::MissingMember)?;Ok(Occupant{slot:slot as u8,position:point(u),class:u.native_class7c,phase:u.native_phase35,flags31:m.flags31,flags71:u.native_initiative_scan.flags71,peer6f:u.native_contact6f,peer70:u.native_contact70,wait72:u.native_wait72})}
 fn store_occupancy_actor(&mut self,index:usize,a:Occupant){let u=&mut self.units[index];u.native_phase35=a.phase;u.native_initiative_scan.flags71=a.flags71;u.native_contact6f=a.peer6f;u.native_contact70=a.peer70;u.native_wait72=a.wait72;if let Some(m)=u.native_slot.and_then(|slot|self.native_group_rosters.members[slot].as_mut()){m.promotion.phase=a.phase;}}
 fn occupancy_hardware(&self,index:usize)->Result<[u8;44],Boundary>{let u=&self.units[index];if let Some(slot)=u.native_hardware_slot{let w=self.native_hardware_pool.get(slot).ok_or(Boundary::MissingHardwareProfile)?;let mut b=w.attributes.bytes;b[23]=w.order.field17;Ok(b)}else{let mut b=self.native_hardware_dummy_attributes.bytes;b[23]=self.native_hardware_dummy.field17;Ok(b)}}
 fn store_occupancy_hardware(&mut self,index:usize,bytes:[u8;44]){if let Some(slot)=self.units[index].native_hardware_slot{let w=&mut self.native_hardware_pool[slot];w.attributes.bytes=bytes;let mut order=w.order;order.field17=bytes[23];w.set_order(order);}else{self.native_hardware_dummy_attributes.bytes=bytes;self.native_hardware_dummy.field17=bytes[23];}}
 ///525a0 calls5ab40 only after its zero-delta early return. Existing
 ///occupancy can resume nested finite heads; its flags clear before thatcall.
 pub(crate) fn prepare_native_line_occupancy(&mut self,index:usize,target:[i16;2])->bool{
  let Some(u)=self.units.get(index)else{return false;};if !self.map.original||u.native_slot.is_none(){return true;}if point(u)==target{return false;}
  if u.native_initiative_scan.flags71&1!=0{if let Err(e)=self.release_native_occupancy(index){self.native_route_boundary=Some(e);return false;}}
  let u=&mut self.units[index];u.native_initiative_scan.flags71&=!4;let hardware=u.native_phase35==2||u.native_class7c==1;let rejected=!hardware&&matches!(u.native_class7c,2|4|5|6);
  if hardware{let mut hw=match self.occupancy_hardware(index){Ok(w)=>w,Err(e)=>{self.native_route_boundary=Some(e);return false;}};hw[23]|=1;self.store_occupancy_hardware(index,hw);}!rejected
 }
 pub(crate) fn occupy_native_terrain(&mut self,index:usize)->Result<(),Boundary>{let mut actor=self.occupancy_actor(index)?;let mut hw=if actor.class==1{self.occupancy_hardware(index)?}else{[0;44]};let result=native::occupy(&mut actor,&mut hw,&mut TerrainEnv(self));self.store_occupancy_actor(index,actor);if actor.class==1{self.store_occupancy_hardware(index,hw);}result.map_err(boundary)}
 ///5ab40, including real finite-head52810/52960 continuation. Its flags
 ///clear before52810 prevents recursion through a new525a0 segment.
 pub(crate) fn release_native_occupancy(&mut self,index:usize)->Result<bool,Boundary>{let mut actor=self.occupancy_actor(index)?;if actor.flags71&1==0{return Ok(false);}let peer=if actor.peer70!=255{Some(self.occupancy_unit_index(usize::from(actor.peer70))?)}else{None};let mut hw=if actor.class==1{self.occupancy_hardware(index)?}else{[0;44]};let mut peers=Vec::new();let result=native::release(&mut actor,&mut hw,&mut TerrainEnv(self),|slot|peers.push(slot));self.store_occupancy_actor(index,actor);if let Some(peer)=peer{if !peers.is_empty(){self.units[peer].native_contact6f=255;}}if actor.class==1{self.store_occupancy_hardware(index,hw);}let resume=result.map_err(boundary)?;
  if resume{loop{let active=self.units.get(index).and_then(|u|u.native_slot).and_then(|slot|self.native_group_rosters.members[slot].as_ref()).is_some_and(|m|m.flags31&4!=0);if !active{break;}if !self.resume_native_reset_path(index){let mut hw=self.occupancy_hardware(index)?;hw[23]=(hw[23]&!2)|1;self.store_occupancy_hardware(index,hw);break;}if self.check_native_reset_path(index)&1==0{break;}}}Ok(true)
 }
 ///The source removal caller owns whether this is before or after31:4
 ///clears. This wrapper never frees W or changes the active bit itself.
 pub(crate) fn release_native_removal_occupancy(&mut self,index:usize){if self.units.get(index).is_some_and(|u|u.native_initiative_scan.flags71&1!=0){if let Err(e)=self.release_native_occupancy(index){self.native_route_boundary=Some(e);}}}
 pub(crate) fn release_native_occupancy_if_ready(&mut self,index:usize)->Result<bool,Boundary>{let mut actor=self.occupancy_actor(index)?;if actor.flags71&1==0{return Ok(false);}let peer_index=self.occupancy_unit_index(usize::from(actor.peer70))?;let u=&self.units[peer_index];let member=u.native_slot.and_then(|slot|self.native_group_rosters.members[slot].as_ref());let peer=Occupant{position:point(u),class:u.native_class7c,flags31:member.map_or(0,|m|m.flags31),..Default::default()};let mut near=false;
  if peer.class!=1{if let Some(m)=member{if m.group!=255{let row=self.native_group_rosters.pool.get(usize::from(m.group)).ok_or(Boundary::MissingGroup(i16::from(m.group)))?;for slot in (0..21).filter_map(|role|row.member(role)){let flags=self.native_group_rosters.members[usize::from(slot)].as_ref().map_or(0,|m|m.flags31);if flags&4==0{continue;}let i=self.occupancy_unit_index(usize::from(slot))?;if native::near_signed_word(actor.position,point(&self.units[i])){near=true;break;}}}}}
  let ready=native::can_release(&mut actor,peer,||near);self.store_occupancy_actor(index,actor);if ready{self.release_native_occupancy(index)?;}Ok(ready)
 }
 ///Single5a080 handler bridge:5a680 owns phase22; the common5c5c0 body
 ///invokes5b470 once before its hatch/contact/movement work and ignores AL.
 pub(crate) fn dispatch_native_occupancy_state(&mut self,index:usize)->Result<bool,Boundary>{let u=self.units.get(index).ok_or(Boundary::MissingActor)?;let phase=u.native_phase35;if phase==22{if self.release_native_occupancy_if_ready(index)?{self.units[index].native_initiative_scan.flags71&=!1;self.reset_native_idle(index);}return Ok(true);}if u.native_class7c==1&&matches!(phase,9|10|53|54|55|56|58|59|60){self.release_native_occupancy_if_ready(index)?;}Ok(false)}
 ///5ba10's actual writer of71:1 and reciprocal70/6f. This API is called
 ///only by an original contact/yield caller, never inferred from proximity.
 pub(crate) fn begin_native_occupancy_handshake(&mut self,index:usize,peer_index:usize)->Result<bool,Boundary>{let actor=self.occupancy_actor(index)?;let peer=self.occupancy_actor(peer_index)?;let footprint=self.units[index].native_footprint18;let plan=native::handshake(actor,peer,|cell|self.dynamic_collision_terrain(cell).and_then(|c|self.native_collision_masks.value(footprint,c))).map_err(boundary)?;if plan==Handshake::Blocked{return Ok(false);}
  if let Handshake::Align(waypoint)=plan{let saved=self.native_group_rosters.current_roster;let group=usize::from(self.native_group_rosters.members[usize::from(actor.slot)].as_ref().ok_or(Boundary::MissingMember)?.group);if group>=240{return Err(Boundary::MissingGroup(group as i16));}self.native_group_rosters.current_roster=Some(group);self.prepend_native_walk_waypoint(index,waypoint);self.resume_native_reset_path(index);self.native_group_rosters.current_roster=saved;let mut hw=self.occupancy_hardware(index)?;hw[23]=(hw[23]&!2)|1;self.store_occupancy_hardware(index,hw);}
  let mut actor=self.occupancy_actor(index)?;let mut peer=self.occupancy_actor(peer_index)?;native::record_handshake(&mut actor,&mut peer);self.store_occupancy_actor(index,actor);self.units[peer_index].native_contact6f=peer.peer6f;if plan==Handshake::Park{self.occupy_native_terrain(index)?;}Ok(true)
 }
}

