 #[test]fn workshop66_permission_is_temporary_and_uses_actual_build_slot_query(){let mut g=field();actors(&mut g,"medium");g.units[0].x=1038.;g.units[0].y=1042.;g.units[0].angle=crate::native_math::angle(0);g.map.terrain_codes.fill(66);g.map.native_terrain_plane.fill(66);let group=g.native_group_rosters.current_roster.unwrap();g.native_group_rosters.pool[group].roster[58]=1;g.native_group_rosters.pool[group].roster[44..46].copy_from_slice(&416i16.to_le_bytes());g.native_group_rosters.pool[group].roster[46..48].copy_from_slice(&516i16.to_le_bytes());g.import_native_world(&crate::json!({"nativeWorldBuildings":[{"nativeSlot":3,"kind":0,"x":400,"y":500,"hp":1,"maxHp":500}]}));let foot=g.units[0].native_footprint18;let mut effective=g.units[0].native_permission1c;native::select_permission(&mut effective,0);let saved=[g.native_collision_masks.value(foot,66).unwrap(),g.native_collision_masks.value(effective,66).unwrap()];let(hit,_)=g.native_wrapped_collision(0,[519,520]).unwrap();assert!(!hit,"live BUILD0 at the group's actual goal admits66");assert_eq!([g.native_collision_masks.value(foot,66).unwrap(),g.native_collision_masks.value(effective,66).unwrap()],saved);g.import_native_world(&crate::json!({"nativeWorldBuildings":[{"nativeSlot":3,"kind":4,"x":400,"y":500,"hp":1,"maxHp":500}]}));let(hit,_)=g.native_wrapped_collision(0,[519,520]).unwrap();assert!(hit,"a live non-workshop BUILD must not open66");assert_eq!([g.native_collision_masks.value(foot,66).unwrap(),g.native_collision_masks.value(effective,66).unwrap()],saved);}
 #[test]fn live_movement_leaf_commits_native_corrected_unit_before_distinct518e0_attempt(){let mut g=field();actors(&mut g,"medium");let terrain=(0..16384).map(|n|(n%67)as u8).collect::<Vec<_>>();g.map.native_terrain_plane=terrain.clone();for y in 0..64{for x in 0..64{g.map.terrain_codes[y*64+x]=terrain[y*128+x];}}let u=&mut g.units[0];u.x=1026.;u.y=1024.;u.angle=crate::native_math::angle(0);u.native_terrain_tag63=0;u.native_field62=1;u.native_counter67=68;u.native_remaining48=4;u.original_motion=Some(crate::original_motion::Segment::new(u.x,u.y,(1018.,1024.)));let result=g.advance_native_walk_position(0).unwrap();let c=result.contact.expect("actual scenario4 from ZNov04DynamicCallerOracle");assert_eq!(c.position,(503,512));assert_eq!(c.attempted,(512,512));assert_eq!(point(&g.units[0]),[503,512]);assert_eq!(g.units[0].native_remaining48,4,"contact does not spend UNIT48");assert_eq!(g.native_route_boundary,None);}
