 #[test]fn apc_follower_with_real_w_restores_occupancy_before_58730_retires_it(){let mut g=field();g.spawn("apc",0,800.,800.,1,None);g.spawn("medium",0,1038.,1032.,1,None);g.spawn("medium",1,1100.,1032.,2,None);g.maintain_native_group_rosters();g.native_group_rosters.set_current_roster(0,1);g.import_native_world(&Value::Null);assert!(g.begin_native_occupancy_handshake(1,2).unwrap());let p=point(&g.units[1]);let slot=g.units[1].native_slot.unwrap();let w=g.units[1].native_hardware_slot.unwrap();assert_eq!(codes(&g,p),[19;4]);g.kill_native_apc_passengers(0,false,false);assert_eq!(codes(&g,p),[0;4]);assert_eq!(g.native_hardware_pool[w].live_marker,-1);assert_eq!(g.native_group_rosters.members[slot].as_ref().unwrap().flags31&4,0);assert_eq!(g.units[2].native_contact6f,255);assert_eq!(g.native_route_boundary,None);}
